mapper.select:
select cci.cert_config_id, cci.cert_config_name, cci.cert_source, cci.competition_series_id, cci.competition_track_id, cci.second_level_code, cci.course_id, cci.training_program_id, cci.cert_period_type, cci.cert_period_time, cci.cert_manager_role, cci.cert_status, cci.cert_link_name, cci.cert_link_url, cci.org_code, cci.awards_name, cci.is_competition, cci.is_course, cci.is_training_program,cci.year, cci.create_by, cci.create_time, cci.update_by,cci. update_time, cci.del_flag, cci.version,cci.competition_stage_id,ctcf.stage_name as competition_stage_name, csi.competition_series_name,csi.competition_name,csi.competition_id,cti.competition_track_name,ctc.second_level_name from cert_config_info cci left join (select a.competition_series_id, a.competition_series_name,b.competition_name,b.competition_id from competition_series_info a left join competition_main_info b on a.competition_id = b.competition_id) csi on cci.competition_series_id = csi.competition_series_id left join competition_track_info cti on cci.competition_track_id = cti.competition_track_id left join competition_track_config ctc on cci.second_level_code = ctc.second_level_code left join competition_stage_config ctcf on cci.competition_stage_id = ctcf.stage_id where cci.del_flag = '0'
and cci.cert_config_name like concat('%', #{certConfigName}, '%')
and cci.cert_source = #{certSource}
and ctcf.stage_id = #{competitionStageId}
and FIND_IN_SET(#{certManagerRole},cci.cert_manager_role)
and cci.competition_series_id in (select a.competition_series_id from competition_series_info a left join competition_main_info b on a.competition_id = b.competition_id where b.competition_name like concat('%', #{competitionName}, '%'))
and cci.competition_stage_id in (select stage_id from competition_stage_config where stage_name like concat('%', #{competitionStageName}, '%'))
and cci.competition_series_id in (select competition_series_id from competition_series_info where competition_series_name like concat('%', #{competitionSeriesName}, '%'))
and cci.competition_track_id in (select competition_track_id from competition_track_info where competition_track_name like concat('%', #{competitionTrackName}, '%'))
and cci.second_level_code in (select second_level_code from competition_track_config where second_level_name like concat('%', #{secondLevelName}, '%')
and cci.competition_series_id = #{competitionSeriesId}
and cci.competition_track_id = #{competitionTrackId}
and cci.second_level_code = #{secondLevelCode}
and cci.cert_status = #{certStatus}
and cci.org_code = #{orgCode}
order by cci.create_time desc

mapper.update:
update cert_config_info
cert_config_name = #{certConfigName}, cert_source = #{certSource}, competition_series_id = #{competitionSeriesId}, competition_stage_id = #{competitionStageId}, competition_track_id = #{competitionTrackId}, second_level_code = #{secondLevelCode}, course_id = #{courseId}, training_program_id = #{trainingProgramId}, cert_period_type = #{certPeriodType}, cert_period_time = #{certPeriodTime}, cert_manager_role = #{certManagerRole}, cert_status = #{certStatus}, cert_link_name = #{certLinkName}, cert_link_url = #{certLinkUrl}, org_code = #{orgCode}, awards_name = #{awardsName}, year = #{year}, is_competition = #{isCompetition}, is_course = #{isCourse}, is_training_program = #{isTrainingProgram}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, version = version+1,
where cert_config_id = #{certConfigId}
